using System.Text.Json;
using Satori.Core;

namespace Satori.Numerics.Tests;

/// <summary>
/// DW06.7: the Q8_K activation quantizer and the integer Q4_K product, checked against an independent FP64
/// reference generated by <c>tools/q8k_reference.py</c> from the pinned ggml implementation. The reference
/// reproduces <c>quantize_row_q8_K_ref</c> and <c>ggml_vec_dot_q4_K_q8_K</c> in Python and shares no code
/// with Satori, so a match is evidence and not a tautology.
/// </summary>
public sealed class Q8KCodecTests
{
    private static readonly JsonElement Fixture = JsonDocument.Parse(
        File.ReadAllText(Path.Combine(GgufTests.Root, "fixtures/operators/q8k-v1.json"))).RootElement;

    private static byte[] Hex(string value) => Convert.FromHexString(value);

    private static float[] Inputs(JsonElement element) =>
        element.EnumerateArray().Select(v => v.GetSingle()).ToArray();

    [Fact]
    public void QuantizerMatchesTheReferenceBytes()
    {
        foreach (var test in Fixture.GetProperty("cases").EnumerateArray())
        {
            string name = test.GetProperty("name").GetString()!;
            float[] input = Inputs(test.GetProperty("input"));
            byte[] expected = Hex(test.GetProperty("block_hex").GetString()!);
            byte[] actual = new byte[Q8KCodec.BytesPerBlock];
            Q8KCodec.QuantizeBlock(input, actual);
            Assert.True(expected.AsSpan().SequenceEqual(actual),
                $"{name}: block bytes differ from the reference quantizer.");
        }
    }

    [Fact]
    public void ScaleAndGroupSumsMatchTheReference()
    {
        foreach (var test in Fixture.GetProperty("cases").EnumerateArray())
        {
            string name = test.GetProperty("name").GetString()!;
            float[] input = Inputs(test.GetProperty("input"));
            byte[] block = new byte[Q8KCodec.BytesPerBlock];
            Q8KCodec.QuantizeBlock(input, block);

            float expectedScale = test.GetProperty("scale").GetSingle();
            Assert.Equal(expectedScale, Q8KCodec.Scale(block), 6);

            var sums = Q8KCodec.GroupSums(block);
            int index = 0;
            foreach (var expected in test.GetProperty("bsums").EnumerateArray())
                Assert.Equal(expected.GetInt32(), sums[index++]);
            Assert.Equal(Q8KCodec.Groups, index);
        }
    }

    [Fact]
    public void IntegerProductMatchesTheReferenceDot()
    {
        foreach (var test in Fixture.GetProperty("cases").EnumerateArray())
        {
            string name = test.GetProperty("name").GetString()!;
            byte[] weights = Hex(test.GetProperty("weights_hex").GetString()!);
            byte[] activation = Hex(test.GetProperty("block_hex").GetString()!);
            double reference = test.GetProperty("dot").GetDouble();
            float actual = Q4KCodec.DotBlockQuantized(weights, activation);
            Assert.True(Math.Abs(actual - reference) <= 1e-3 + 1e-4 * Math.Abs(reference),
                $"{name} dot: {actual} vs {reference}");
        }
    }

    [Fact]
    public void ZeroActivationBlockIsZeroInBothForms()
    {
        byte[] weights = Hex(Fixture.GetProperty("cases")[0].GetProperty("weights_hex").GetString()!);
        byte[] activation = new byte[Q8KCodec.BytesPerBlock];
        activation.AsSpan(Q8KCodec.QuantsOffset, Q8KCodec.ElementsPerBlock).Fill(0x7F);
        Assert.Equal(0f, Q4KCodec.DotBlockQuantized(weights, activation));
        Q8KCodec.QuantizeBlock(new float[Q8KCodec.ElementsPerBlock], activation);
        Assert.True(Q8KCodec.IsZero(activation));
        Assert.Equal(0, Q4KCodec.DotProduct(weights, activation));
        Assert.Equal(0, Q4KCodec.MinProduct(weights, activation));
    }

    [Fact]
    public void QuantizationErrorStaysInsideOneStep()
    {
        var random = new Random(20261014);
        float[] input = new float[Q8KCodec.ElementsPerBlock];
        for (int i = 0; i < input.Length; i++) input[i] = (float)(random.NextDouble() * 2 - 1);
        byte[] block = new byte[Q8KCodec.BytesPerBlock];
        Q8KCodec.QuantizeBlock(input, block);
        float scale = Q8KCodec.Scale(block);
        var codes = Q8KCodec.Codes(block);
        float largest = input.Max(Math.Abs);
        Assert.True(largest > 0);
        // Every reconstructed value must stay within one code step of the original, and the step cannot
        // exceed largest/127 by construction.
        float step = Math.Abs(scale);
        for (int i = 0; i < input.Length; i++)
        {
            float reconstructed = scale * codes[i];
            Assert.True(Math.Abs(reconstructed - input[i]) <= step,
                $"element {i}: {reconstructed} vs {input[i]} exceeds one step {step}.");
        }
    }

    [Fact]
    public void QuantizeRowProducesOneBlockPer256Floats()
    {
        float[] input = new float[768];
        for (int i = 0; i < input.Length; i++) input[i] = (float)Math.Sin(i * 0.01);
        byte[] output = new byte[Q8KCodec.RowBytes(768)];
        Q8KCodec.QuantizeRow(input, output);
        for (int block = 0; block < 3; block++)
        {
            byte[] one = new byte[Q8KCodec.BytesPerBlock];
            Q8KCodec.QuantizeBlock(input.AsSpan(block * 256, 256), one);
            Assert.True(one.AsSpan().SequenceEqual(output.AsSpan(block * Q8KCodec.BytesPerBlock, Q8KCodec.BytesPerBlock)));
        }
    }
}
